package net.civeira.phylax.features.access.tenantconfig.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class WebauthnEnabledVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property webauthn enabled of tenant config ")
  void test_webauthn_enabled_v_o_builder() {
    Assertions.assertFalse(WebauthnEnabledVO.nullValue().isWebauthnEnabled(),
        "A empty vo should have a null value");
    Assertions.assertFalse(WebauthnEnabledVO.tryFrom(null).isWebauthnEnabled(),
        "With a null value, no present result");
    Assertions.assertEquals(true, WebauthnEnabledVO.from(true).isWebauthnEnabled());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> WebauthnEnabledVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + true + "]", WebauthnEnabledVO.from(true).toString());
  }
}
